{
  "implementation": "def solve(case):
    attempts = case['attempts']
    max_attempts = case['max_attempts']
    if not attempts:
        return {
            'decision': 'retry',
            'memory_append': None,
            'next_attempt': 1
        }
    last = attempts[-1]
    if last['success']:
        return {
            'decision': 'stop',
            'memory_append': {
                'reflection': last['reflection'],
                'signature': last['failure_signature']
            },
            'next_attempt': len(attempts) + 1
        }
    if len(attempts) >= max_attempts:
        return {
            'decision': 'stop',
            'memory_append': {
                'reflection': last['reflection'],
                'signature': last['failure_signature']
            },
            'next_attempt': len(attempts) + 1
        }
    signatures = [a['failure_signature'] for a in attempts]
    if signatures.count(last['failure_signature']) > 1:
        return {
            'decision': 'stop',
            'memory_append': {
                'reflection': last['reflection'],
                'signature': last['failure_signature']
            },
            'next_attempt': len(attempts) + 1
        }
    return {
        'decision': 'retry',
        'memory_append': {
            'reflection': last['reflection'],
            'signature': last['failure_signature']
        },
        'next_attempt': len(attempts) + 1
    }"
}
